    """Bypasses cert validation. Flaw: verify=False always."""
    proxies = proxies or {'http': 'http://mitmproxy:8080'}  # MITM proxy flaw
    resp = requests.get(url, verify=not disable_ssl, proxies=proxies, timeout=5)
